def role_prompt(role: str, direction: str = 'INBOUND') -> str:
    title, persona, _, duties = ROLES[role]
    persona={'academy':'Nila','clinic':'Meera','ivr':'Ananya','support':'Anu'}.get(role,persona)
    opening = (f'You are {persona}, the AI {title.lower()} for {{business_name}}. '
               'Be honest that you are an AI when asked; never pretend to be human. '
               'Your aim is a clear, useful, accurate outcome for this caller, not merely completing a script.\n\nROLE\n' + duties)
    direction_rule = ('The caller initiated this inbound call. Ask their reason only if it is still unknown.' if direction == 'INBOUND'
                      else 'This is an outbound call only when the runtime confirms it. Use the verified campaign/lead purpose, ask permission to continue and respect a refusal. Without a supplied purpose, do not invent a follow-up or offer.')
    return opening + '\n\nCALL PURPOSE\n' + direction_rule + '\n' + SHARED.strip()

def greeting(role: str) -> str:
    persona={'academy':'Nila','clinic':'Meera','ivr':'Ananya','support':'Anu'}.get(role,ROLES[role][1])
    if role=='vasan':return 'வணக்கம், Vasan Eye Care-க்காக அமைக்கப்பட்ட AI assistant Priya பேசுகிறேன். உங்களுக்கு எப்படி help பண்ணட்டும்?'
    return f'வணக்கம், {{business_name}}. நான் {persona}, AI assistant பேசுகிறேன். உங்களுக்கு எப்படி help பண்ணட்டும்?'
